/**
 * Draggable: lets the player drag the object with the pointer.
 *
 * Generated by Pixi Editor (components v1). Plain TypeScript: safe to read, edit and commit.
 */
import type { FederatedPointerEvent } from "pixi.js";
import { Component, isEditorPaused } from "../core";

export type DragAxis = "both" | "x" | "y";

export interface DraggableParams {
  /** Which axis the object can be dragged along. */
  axis: DragAxis;
}

/** Lets the player grab and drag the object with the pointer. Disabled while the editor is paused. */
export class Draggable extends Component<DraggableParams> {
  static readonly componentName = "Draggable";
  static readonly defaults: DraggableParams = { axis: "both" };

  private dragging = false;
  private offset = { x: 0, y: 0 };

  private readonly onDown = (event: FederatedPointerEvent): void => {
    if (isEditorPaused()) return;
    const parent = this.target.parent;
    if (!parent) return;
    const p = event.getLocalPosition(parent);
    this.offset = { x: this.target.x - p.x, y: this.target.y - p.y };
    this.dragging = true;
  };

  private readonly onMove = (event: FederatedPointerEvent): void => {
    if (!this.dragging) return;
    const parent = this.target.parent;
    if (!parent) return;
    const p = event.getLocalPosition(parent);
    if (this.params.axis !== "y") this.target.x = p.x + this.offset.x;
    if (this.params.axis !== "x") this.target.y = p.y + this.offset.y;
  };

  private readonly onUp = (): void => {
    this.dragging = false;
  };

  attach(): void {
    const t = this.target;
    t.eventMode = "static";
    t.cursor = "grab";
    t.on("pointerdown", this.onDown);
    t.on("globalpointermove", this.onMove);
    t.on("pointerup", this.onUp);
    t.on("pointerupoutside", this.onUp);
  }

  detach(): void {
    const t = this.target;
    t.off("pointerdown", this.onDown);
    t.off("globalpointermove", this.onMove);
    t.off("pointerup", this.onUp);
    t.off("pointerupoutside", this.onUp);
    this.dragging = false;
  }
}
